/**
 * The word levels the functions carry, by target language (generated by
 * `dilbaz-content levels-module` after a target pack build).
 */
import { enLevels } from "./en.ts";
import { Lexicon } from "./levels.ts";

const data = { en: enLevels } as const;
const lexicons = new Map<string, Lexicon>();

/** The lexicon of [l2], built on first use; null for a language without one. */
export function lexiconFor(l2: string): Lexicon | null {
  const cached = lexicons.get(l2);
  if (cached) return cached;
  if (!Object.hasOwn(data, l2)) return null;
  const lexicon = new Lexicon(data[l2 as keyof typeof data]);
  lexicons.set(l2, lexicon);
  return lexicon;
}
